import { htmlStringDecode } from '@/plp/utils/htmlStringDecode';
import { Product } from '@/plp/data/models/product';

/**
 * Returns the HTML-decoded product name, or a fallback value when the
 * product name is not available.
 */
const getProductName = (product: Product, fallback = ''): string => {
  return product.name !== null ? htmlStringDecode(product.name) ?? fallback : fallback;
};

export { getProductName };

